from pathlib import Path

import torch
from transformers import GenerationMixin, PreTrainedModel, PretrainedConfig
from transformers.modeling_outputs import CausalLMOutputWithPast

from reasoning_from_scratch.qwen3 import (
    QWEN_CONFIG_06_B,
    Qwen3Model,
    Qwen3Tokenizer,
    download_qwen3_small,
)


MODEL_FILENAMES = {
    "base": "qwen3-0.6B-base.pth",
    "reasoning": "qwen3-0.6B-reasoning.pth",
}

TOKENIZER_FILENAMES = {
    "base": "tokenizer-base.json",
    "reasoning": "tokenizer-reasoning.json",
}


def _dtype_to_name(dtype_value):
    if isinstance(dtype_value, torch.dtype):
        return str(dtype_value).removeprefix("torch.")
    return dtype_value


def _qwen_cfg_to_jsonable(model_cfg):
    model_cfg = dict(model_cfg)
    model_cfg["dtype"] = _dtype_to_name(model_cfg["dtype"])
    return model_cfg


def _qwen_cfg_from_jsonable(model_cfg):
    model_cfg = dict(model_cfg)
    if isinstance(model_cfg["dtype"], str):
        model_cfg["dtype"] = getattr(torch, model_cfg["dtype"])
    return model_cfg


class Qwen3LocalWrapperConfig(PretrainedConfig):
    model_type = "qwen3_local_wrapper"

    def __init__(
        self,
        qwen_cfg=None,
        tokenizer_kind="base",
        pad_token_id=None,
        eos_token_id=None,
        **kwargs,
    ):
        if qwen_cfg is None:
            qwen_cfg = dict(QWEN_CONFIG_06_B)

        self.qwen_cfg = _qwen_cfg_to_jsonable(qwen_cfg)
        self.tokenizer_kind = tokenizer_kind
        self.vocab_size = qwen_cfg["vocab_size"]
        self.hidden_size = qwen_cfg["emb_dim"]
        self.num_attention_heads = qwen_cfg["n_heads"]
        self.num_key_value_heads = qwen_cfg["n_kv_groups"]
        self.num_hidden_layers = qwen_cfg["n_layers"]
        self.max_position_embeddings = qwen_cfg["context_length"]
        kwargs.pop("tie_word_embeddings", None)

        super().__init__(
            pad_token_id=pad_token_id,
            eos_token_id=eos_token_id,
            dtype=self.qwen_cfg["dtype"],
            use_cache=False,
            tie_word_embeddings=False,
            **kwargs,
        )


class Qwen3LocalWrapperForCausalLM(PreTrainedModel, GenerationMixin):
    config_class = Qwen3LocalWrapperConfig
    main_input_name = "input_ids"

    def __init__(self, config):
        super().__init__(config)
        self.model = Qwen3Model(_qwen_cfg_from_jsonable(config.qwen_cfg))
        self.generation_config.pad_token_id = config.pad_token_id
        self.generation_config.eos_token_id = config.eos_token_id
        self.generation_config.use_cache = False

    def get_input_embeddings(self):
        return self.model.tok_emb

    def set_input_embeddings(self, value):
        self.model.tok_emb = value

    def get_output_embeddings(self):
        return self.model.out_head

    def set_output_embeddings(self, new_embeddings):
        self.model.out_head = new_embeddings

    def forward(
        self,
        input_ids=None,
        attention_mask=None,
        labels=None,
        use_cache=None,
        return_dict=None,
        **kwargs,
    ):
        del attention_mask, use_cache, kwargs
        if input_ids is None:
            raise ValueError("input_ids must be provided.")

        logits = self.model(input_ids)

        loss = None
        if labels is not None:
            shift_logits = logits[..., :-1, :].contiguous()
            shift_labels = labels[..., 1:].contiguous()
            loss = torch.nn.functional.cross_entropy(
                shift_logits.view(-1, shift_logits.size(-1)),
                shift_labels.view(-1),
                ignore_index=-100,
            )

        if return_dict is False:
            outputs = (logits,)
            return ((loss,) + outputs) if loss is not None else outputs

        return CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
        )

    def prepare_inputs_for_generation(
        self,
        input_ids,
        attention_mask=None,
        **kwargs,
    ):
        del attention_mask, kwargs
        # This wrapper keeps things simple and recomputes from the full prefix
        # during generation instead of adapting the scratch KV cache to HF's
        # cache classes.
        return {"input_ids": input_ids, "use_cache": False}


def build_tokenizer(tokenizer_kind="base", tokenizer_path=None, local_dir="qwen3"):
    if tokenizer_path is None:
        download_qwen3_small(
            kind=tokenizer_kind,
            tokenizer_only=True,
            out_dir=local_dir,
        )
        tokenizer_path = Path(local_dir) / TOKENIZER_FILENAMES[tokenizer_kind]
    else:
        tokenizer_path = Path(tokenizer_path)

    if tokenizer_kind == "reasoning":
        return Qwen3Tokenizer(
            tokenizer_file_path=tokenizer_path,
            apply_chat_template=True,
            add_generation_prompt=True,
            add_thinking=True,
        )

    return Qwen3Tokenizer(tokenizer_file_path=tokenizer_path)


def build_model(
    tokenizer_kind="base",
    model_path=None,
    tokenizer=None,
    local_dir="qwen3",
):
    if tokenizer is None:
        tokenizer = build_tokenizer(
            tokenizer_kind=tokenizer_kind,
            local_dir=local_dir,
        )

    if model_path is None:
        download_qwen3_small(
            kind=tokenizer_kind,
            tokenizer_only=False,
            out_dir=local_dir,
        )
        model_path = Path(local_dir) / MODEL_FILENAMES[tokenizer_kind]
    else:
        model_path = Path(model_path)

    try:
        state_dict = torch.load(model_path, map_location="cpu", weights_only=True)
    except TypeError:
        state_dict = torch.load(model_path, map_location="cpu")

    config = Qwen3LocalWrapperConfig(
        qwen_cfg=QWEN_CONFIG_06_B,
        tokenizer_kind=tokenizer_kind,
        pad_token_id=tokenizer.pad_token_id,
        eos_token_id=tokenizer.eos_token_id,
    )
    model = Qwen3LocalWrapperForCausalLM(config)
    model.model.load_state_dict(state_dict)
    return model


def build_model_and_tokenizer(
    tokenizer_kind="base",
    model_path=None,
    tokenizer_path=None,
    local_dir="qwen3",
):
    tokenizer = build_tokenizer(
        tokenizer_kind=tokenizer_kind,
        tokenizer_path=tokenizer_path,
        local_dir=local_dir,
    )
    model = build_model(
        tokenizer_kind=tokenizer_kind,
        model_path=model_path,
        tokenizer=tokenizer,
        local_dir=local_dir,
    )
    return model, tokenizer


def format_distilled_answer(entry, use_think_tokens=False):
    content = str(entry["message_content"]).replace("<think>", "").replace("</think>", "").strip()
    if not content:
        raise ValueError("Missing non-empty 'message_content' field.")

    thinking = str(entry.get("message_thinking", "")).replace("<think>", "").replace("</think>", "").strip()

    if use_think_tokens:
        return f"<think>{thinking}</think>\n\n{content}"

    if thinking:
        return f"{thinking}\n\n{content}"

    return content

def compute_rope_params(head_dim, theta_base=10_000, context_length=4096, dtype=torch.float32):
    assert head_dim % 2 == 0, "Embedding dimension must be even"

    # Compute the inverse frequencies
    inv_freq = 1.0 / (theta_base ** (torch.arange(0, head_dim, 2, dtype=dtype)[: (head_dim // 2)].float() / head_dim))

    # Generate position indices
    positions = torch.arange(context_length, dtype=dtype)

    # Compute the angles
    angles = positions.unsqueeze(1) * inv_freq.unsqueeze(0)  # Shape: (context_length, head_dim // 2)

    # Expand angles to match the head_dim
    angles = torch.cat([angles, angles], dim=1)  # Shape: (context_length, head_dim)

    # Precompute sine and cosine
    cos = torch.cos(angles)
    sin = torch.sin(angles)

    return cos, sin


def apply_rope(x, cos, sin, offset=0):
    # x: (batch_size, num_heads, seq_len, head_dim)
    batch_size, num_heads, seq_len, head_dim = x.shape
    assert head_dim % 2 == 0, "Head dimension must be even"

    # Split x into first half and second half
    x1 = x[..., : head_dim // 2]  # First half
    x2 = x[..., head_dim // 2:]  # Second half

    # Adjust sin and cos shapes
    cos = cos[offset:offset + seq_len, :].unsqueeze(0).unsqueeze(0)  # Shape: (1, 1, seq_len, head_dim)
    sin = sin[offset:offset + seq_len, :].unsqueeze(0).unsqueeze(0)

    # Apply the rotary transformation
    rotated = torch.cat((-x2, x1), dim=-1)
    x_rotated = (x * cos) + (rotated * sin)

    # It's ok to use lower-precision after applying cos and sin rotation
    return x_rotated.to(dtype=x.dtype)


class RMSNorm(nn.Module):
    def __init__(self, emb_dim, eps=1e-6, bias=False, qwen3_compatible=True):
        super().__init__()
        self.eps = eps
        self.qwen3_compatible = qwen3_compatible
        self.scale = nn.Parameter(torch.ones(emb_dim))
        self.shift = nn.Parameter(torch.zeros(emb_dim)) if bias else None

    def forward(self, x):
        input_dtype = x.dtype

        if self.qwen3_compatible:
            x = x.to(torch.float32)

        variance = x.pow(2).mean(dim=-1, keepdim=True)
        norm_x = x * torch.rsqrt(variance + self.eps)
        norm_x = norm_x * self.scale

        if self.shift is not None:
            norm_x = norm_x + self.shift

        return norm_x.to(input_dtype)


class Qwen3Tokenizer:
    _SPECIALS = [
        "<|endoftext|>",
        "<|im_start|>", "<|im_end|>",
        "<|object_ref_start|>", "<|object_ref_end|>",
        "<|box_start|>", "<|box_end|>",
        "<|quad_start|>", "<|quad_end|>",
        "<|vision_start|>", "<|vision_end|>",
        "<|vision_pad|>", "<|image_pad|>", "<|video_pad|>",
    ]
    _SPLIT_RE = re.compile(r"(<\|[^>]+?\|>)")

    def __init__(self, tokenizer_file_path="tokenizer-base.json",
                 apply_chat_template=False,
                 add_generation_prompt=False,
                 add_thinking=False):
        from tokenizers import Tokenizer

        self.apply_chat_template = apply_chat_template
        self.add_generation_prompt = add_generation_prompt
        self.add_thinking = add_thinking

        tok_path = Path(tokenizer_file_path)
        if not tok_path.is_file():
            raise FileNotFoundError(
                f"Tokenizer file '{tok_path}' not found. Please ensure it's available."
            )

        self._tok = Tokenizer.from_file(str(tok_path))
        self._special_to_id = {t: self._tok.token_to_id(t) for t in self._SPECIALS}

        self.pad_token = "<|endoftext|>"
        self.pad_token_id = self._special_to_id.get(self.pad_token)

        # Match HF behavior: chat model → <|im_end|>, base model → <|endoftext|>
        fname = tok_path.name.lower()
        if "base" in fname and "reasoning" not in fname:
            self.eos_token = "<|endoftext|>"
        else:
            self.eos_token = "<|im_end|>"
        self.eos_token_id = self._special_to_id.get(self.eos_token)

    def encode(self, prompt, chat_wrapped=None):
        if chat_wrapped is None:
            chat_wrapped = self.apply_chat_template

        stripped = prompt.strip()
        if stripped in self._special_to_id and "\n" not in stripped:
            return [self._special_to_id[stripped]]

        if chat_wrapped:
            prompt = self._wrap_chat(prompt)

        ids = []
        for part in filter(None, self._SPLIT_RE.split(prompt)):
            if part in self._special_to_id:
                ids.append(self._special_to_id[part])
            else:
                ids.extend(self._tok.encode(part).ids)
        return ids

    def decode(self, token_ids):
        return self._tok.decode(token_ids, skip_special_tokens=False)

    def _wrap_chat(self, user_msg):
        s = f"<|im_start|>user\n{user_msg}<|im_end|>\n"
        if self.add_generation_prompt:
            s += "<|im_start|>assistant"
            if self.add_thinking:
                s += "\n"  # insert no <think> tag, just a new line
            else:
                s += "\n<think>\n\n</think>\n\n"
        return s


class KVCache:
    def __init__(self, n_layers):
        self.cache = [None] * n_layers

    def get(self, layer_idx):
        return self.cache[layer_idx]

    def update(self, layer_idx, value):
        self.cache[layer_idx] = value

    def get_all(self):
        return self.cache

    def reset(self):
        for i in range(len(self.cache)):
            self.cache[i] = None


def download_qwen3_small(kind="base", tokenizer_only=False, out_dir="."):
    files = {
        "base": {"model": "qwen3-0.6B-base.pth", "tokenizer": "tokenizer-base.json"},
        "reasoning": {"model": "qwen3-0.6B-reasoning.pth", "tokenizer": "tokenizer-reasoning.json"},
    }
    if kind not in files:
        raise ValueError("kind must be 'base' or 'reasoning'")

    repo = "rasbt/qwen3-from-scratch"
    hf_fmt = "https://huggingface.co/{repo}/resolve/main/{file}"
    backup_root = "https://f001.backblazeb2.com/file/reasoning-from-scratch/qwen3-0.6B"
    targets = ["tokenizer"] if tokenizer_only else ["model", "tokenizer"]

    for key in targets:
        fname = files[kind][key]
        primary = hf_fmt.format(repo=repo, file=fname)
        backup = f"{backup_root}/{fname}"
        download_file(primary, out_dir=out_dir, backup_url=backup)


def download_qwen3_grpo_checkpoints(
    grpo_type="no_kl",
    step="00050",
    out_dir=".",
):
    mapper = {
        "no_kl": "grpo_original_no_kl",
        "tracking": "7_3_plus_tracking/checkpoints",
        "clip_ratio": "7_4_plus_clip_ratio/checkpoints",
        "kl": "7_5_plus_kl/checkpoints",
        "format_reward": "7_6_plus_format_reward/checkpoints",
    }
    if grpo_type not in mapper:
        raise ValueError(f"only grpo_type in {mapper.keys()} are supported for now")

    repo = "rasbt/qwen3-from-scratch-grpo-checkpoints"
    step = str(step)
    if step.isdigit():
        step = step.zfill(5)
    fname = f"qwen3-0.6B-rlvr-grpo-step{step}.pth"
    primary = f"https://huggingface.co/{repo}/resolve/main/{mapper[grpo_type]}/{fname}"

    backup = None
    if grpo_type == "no_kl" and step == "00050":
        backup_root = (
            "https://f001.backblazeb2.com/file/"
            "reasoning-from-scratch/qwen3-0.6B-checkpoints"
        )
        fname = (
            "grpo_original_no_kl/qwen3-0.6B-rlvr-grpo-step00050.pth"
        )
        backup = f"{backup_root}/{fname}"

    return download_file(primary, out_dir=out_dir, backup_url=backup)


